def classify_announcement(text):
    # A lightweight first pass: keyword and NER based routing
    # before any heavier finance-specific NLP model runs.
    flags = []
    if 'related party' in text.lower():
        flags.append('related_party_transaction')
    if 'credit rating' in text.lower():
        flags.append('rating_action')
    if 'board meeting' in text.lower():
        flags.append('board_outcome')
    return flags

while True:
    for announcement in fetch_new_announcements():
        if announcement['id'] in SEEN_IDS:
            continue
        SEEN_IDS.add(announcement['id'])
        tags = classify_announcement(announcement['text'])
